/**
 * What an authenticated route's call receives alongside its input.
 *
 * It carries more than the token because rotating credentials needs more than
 * the token: POST /api/token/refresh exchanges the refresh token and must write
 * the replacement back to the session it came from.
 */
export interface DemoAuthContext {
  /** The credential this route's auth mode resolved — a session access token, or an MFA challenge token. */
  token: string;
  /** The session's refresh token. Empty on MFA-token routes, or when the tenant returned none. */
  refreshToken: string;
  /** The session id, so a call that rotates tokens can store the replacement. */
  sessionId: string;
}

/** Built from what the auth middleware attached; handlers never re-read a cookie. */
function authContext(req: Request): DemoAuthContext {
  const r = req as Request & { demoToken?: string; demoRefreshToken?: string; demoSessionId?: string };
  return {
    token: r.demoToken ?? '',
    refreshToken: r.demoRefreshToken ?? '',
    sessionId: r.demoSessionId ?? '',
  };
}

function readConfig(res: Response, envVar: string): string | undefined {
  const value = process.env[envVar];
  if (!value) {
    res.status(500).json({
      error: `${envVar} is not set`,
      hint: `this route needs ${envVar} in demo/.env — see demo/.env.example`,
    });
    return undefined;
  }
  return value;
}

function missingField(res: Response, field: string): void {
  res.status(400).json({ error: 'missing required field', field });
}

